          "Năng lực số: Sáng tạo nội dung số (Chỉ báo 3.1TC1b): Học sinh thể hiện bản thân thông qua việc nhập các dữ liệu chữ và số đơn giản đúng kỹ thuật trên trình soạn thảo cơ bản sau khi đã định vị đúng hàng phím cơ sở; An toàn và Bảo vệ sức khỏe (Chỉ báo 4.3TC1a): Thực hiện đúng tư thế ngồi chuẩn (thẳng lưng, đúng khoảng cách mắt) và thả lỏng cơ tay khi thao tác để bảo vệ sức khỏe thể chất; Giải quyết vấn đề (Chỉ báo 5.2TC1b): Học sinh biết tự đưa ra quyết định lựa chọn công cụ điều hướng phù hợp (chuột hoặc phím mũi tên) để giải quyết nhiệm vụ đưa viên bi về đích",
          "Năng lực AI: Tư duy lấy con người làm trung tâm (NLa) - Học sinh hiểu rằng bàn phím, chuột hay các trợ lý AI thông minh đều là công cụ do con người tạo ra nhằm mục đích phục vụ cuộc sống. Công nghệ luôn hoạt động dưới quyền chỉ huy, điều khiển và ra lệnh trực tiếp của con người; Đạo đức AI (NLb): Thực hiện nguyên tắc Không gây hại: Có ý thức bảo vệ thiết bị phần cứng (thao tác chuột và phím nhẹ nhàng, không đập phá); không tự ý chỉnh sửa, phá hỏng sản phẩm số của bạn học. Thiết kế hệ thống AI (NLd): Làm quen với luồng thông tin Dữ liệu đầu vào (Input) và Kết quả đầu ra (Output). Học sinh biết rằng khi đầu vào sai (thao tác nhầm), hệ thống sẽ phản hồi lỗi, từ đó biết tự kiểm tra, nhận diện lỗi và điều chỉnh hành động gõ phím để đạt kết quả chính xác",
